create extension if not exists pgcrypto;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique,avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.videos(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,original_url text not null,normalized_url text not null,platform text not null check(platform in('YouTube','Instagram','TikTok','Facebook','X','Reddit','Vimeo','Other')),title text not null default '',description text,thumbnail_url text,author_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,normalized_url));
create table if not exists public.collections(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,description text,icon text not null default 'folder',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,name));
create table if not exists public.collection_videos(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,collection_id uuid not null references public.collections(id) on delete cascade,video_id uuid not null references public.videos(id) on delete cascade,created_at timestamptz not null default now(),unique(collection_id,video_id));
create index if not exists videos_user_created_idx on public.videos(user_id,created_at desc);create index if not exists videos_user_platform_idx on public.videos(user_id,platform);create index if not exists collections_user_name_idx on public.collections(user_id,name);create index if not exists collection_videos_user_collection_idx on public.collection_videos(user_id,collection_id,created_at desc);create index if not exists collection_videos_video_idx on public.collection_videos(video_id);
alter table public.profiles enable row level security;alter table public.videos enable row level security;alter table public.collections enable row level security;alter table public.collection_videos enable row level security;
create policy profiles_select on public.profiles for select using(id=auth.uid());create policy profiles_insert on public.profiles for insert with check(id=auth.uid());create policy profiles_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());create policy profiles_delete on public.profiles for delete using(id=auth.uid());
create policy videos_select on public.videos for select using(user_id=auth.uid());create policy videos_insert on public.videos for insert with check(user_id=auth.uid());create policy videos_update on public.videos for update using(user_id=auth.uid()) with check(user_id=auth.uid());create policy videos_delete on public.videos for delete using(user_id=auth.uid());
create policy collections_select on public.collections for select using(user_id=auth.uid());create policy collections_insert on public.collections for insert with check(user_id=auth.uid());create policy collections_update on public.collections for update using(user_id=auth.uid()) with check(user_id=auth.uid());create policy collections_delete on public.collections for delete using(user_id=auth.uid());
create policy cv_select on public.collection_videos for select using(user_id=auth.uid() and exists(select 1 from public.collections c where c.id=collection_id and c.user_id=auth.uid()) and exists(select 1 from public.videos v where v.id=video_id and v.user_id=auth.uid()));create policy cv_insert on public.collection_videos for insert with check(user_id=auth.uid() and exists(select 1 from public.collections c where c.id=collection_id and c.user_id=auth.uid()) and exists(select 1 from public.videos v where v.id=video_id and v.user_id=auth.uid()));create policy cv_update on public.collection_videos for update using(user_id=auth.uid() and exists(select 1 from public.collections c where c.id=collection_id and c.user_id=auth.uid()) and exists(select 1 from public.videos v where v.id=video_id and v.user_id=auth.uid())) with check(user_id=auth.uid() and exists(select 1 from public.collections c where c.id=collection_id and c.user_id=auth.uid()) and exists(select 1 from public.videos v where v.id=video_id and v.user_id=auth.uid()));create policy cv_delete on public.collection_videos for delete using(user_id=auth.uid() and exists(select 1 from public.collections c where c.id=collection_id and c.user_id=auth.uid()) and exists(select 1 from public.videos v where v.id=video_id and v.user_id=auth.uid()));
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at();create trigger videos_updated before update on public.videos for each row execute function public.set_updated_at();create trigger collections_updated before update on public.collections for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username) values(new.id,coalesce(new.raw_user_meta_data->>'username',split_part(new.email,'@',1))) on conflict(id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
